def transform(grid):
    R=len(grid); C=len(grid[0])
    rs=[r for r in range(R) for c in range(C) if grid[r][c]!=0]
    cs=[c for r in range(R) for c in range(C) if grid[r][c]!=0]
    cr=(min(rs)+max(rs))//2; cc=(min(cs)+max(cs))//2
    out=[row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c]!=0:
                for r2,c2 in [(r,2*cc-c),(2*cr-r,c),(2*cr-r,2*cc-c)]:
                    if 0<=r2<R and 0<=c2<C: out[r2][c2]=grid[r][c]
    return out

def transform(grid):
    R=len(grid); C=len(grid[0])
    rs=[r for r in range(R) for c in range(C) if grid[r][c]!=0]
    cs=[c for r in range(R) for c in range(C) if grid[r][c]!=0]
    cr=(min(rs)+max(rs))//2; cc=(min(cs)+max(cs))//2
    rad=max(abs(r-cr)+abs(c-cc) for r in range(R) for c in range(C) if grid[r][c]!=0)
    out=[row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c]!=0:
                for r2,c2 in [(r,2*cc-c),(2*cr-r,c),(2*cr-r,2*cc-c)]:
                    if 0<=r2<R and 0<=c2<C: out[r2][c2]=grid[r][c]
    for r in range(R):
        for c in range(C):
            if abs(r-cr)+abs(c-cc)==rad:
                out[r][c]=3
    return out

def transform(grid):
    R=len(grid); C=len(grid[0])
    cr=(R-1)//2; cc=(C-1)//2
    out=[row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c]!=0:
                for r2,c2 in [(r,2*cc-c),(2*cr-r,c),(2*cr-r,2*cc-c)]:
                    if 0<=r2<R and 0<=c2<C: out[r2][c2]=grid[r][c]
