def transform(grid):
    R=len(grid); C=len(grid[0])
    pts=[(r,c) for r in range(R) for c in range(C) if grid[r][c]!=0]
    cr=round(sum(p[0] for p in pts)/len(pts)); cc=round(sum(p[1] for p in pts)/len(pts))
    out=[row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c]!=0:
                for r2,c2 in [(r,2*cc-c),(2*cr-r,c),(2*cr-r,2*cc-c)]:
